/*
draw hue from angle between nearest two points (not related to mouse).
find 2 points closest to current pixel.
get angle between that 2 points.
draw as hue.
*/

#define PI 3.14159265358979323846
#define PI2 6.28318530717958647693

#define pointsLen 10
vec2 points[pointsLen] = vec2[](
vec2(0.1, 0.1),
vec2(0.3, 0.2),
vec2(0.5, 0.1),
vec2(0.7, 0.3),
vec2(0.9, 0.2),
vec2(0.1, 0.5),
vec2(0.3, 0.7),
vec2(0.5, 0.9),
vec2(0.7, 0.5),
vec2(0.9, 0.8)
);

vec3 hsv2rgb(vec3 c) {
  vec3 rgb = clamp(abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0);
  return c.z * mix(vec3(1.0), rgb, c.y);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
vec2 uv = fragCoord / iResolution.xy;
vec2 mouse = iMouse.xy / iResolution.xy;
float time=iTime+2.;

// Avoid dull initial
if (iMouse.x <= 0.0) {
mouse = vec2(0.5, 0.4); // Default mouse position
}


// Variables to store the two nearest points
float minDistance1 = 1e6; // First nearest distance
float minDistance2 = 1e6; // Second nearest distance
vec2 nearestPoint1 = vec2(0.0); // First nearest point
vec2 nearestPoint2 = vec2(0.0); // Second nearest point

// Find the two nearest points to the current pixel
for (int i = 0; i < pointsLen; i++) {
    float distance = length(uv - points[i]);
    if (distance < minDistance1) {
        // Update the second nearest point before updating the first
        minDistance2 = minDistance1;
        nearestPoint2 = nearestPoint1;

        // Update the first nearest point
        minDistance1 = distance;
        nearestPoint1 = points[i];
    } else if (distance < minDistance2) {
        // Update the second nearest point
        minDistance2 = distance;
        nearestPoint2 = points[i];
    }
}


vec2 p1 = nearestPoint1;
vec2 p2 = nearestPoint2;
if(mod(time, 4.0)<2.){
    // Order nearestPoint1 and nearestPoint2 to ensure consistent angle
    if (p1.x > p2.x || (p1.x == p2.x && p1.y > p2.y)) {
        vec2 temp = p1;
        p1 = p2;
        p2 = temp;
    }
}

// Calculate the angle between the ordered nearest points
vec2 vectorBetweenOrdered = p2 - p1;
float angle = atan(vectorBetweenOrdered.y, vectorBetweenOrdered.x);

float hue = mod(time, 8.0)<4.? angle: (angle + PI) / PI2*2.; // Map angle to [0, 1]


// Use the distance to the nearest point for brightness and saturation
float brightness = clamp(1.0 - minDistance1*mouse.x*6., 0.0, 1.0); // Invert distance for brightness

vec3 hsvColor = vec3(hue, 1., brightness);
vec3 rgbColor = hsv2rgb(hsvColor);

fragColor = vec4(rgbColor, 1.0);
}
